content.content:
bin/price:3:echo $(( ($1 * 90 + 99) / 100 ))
bin/quote:3:echo "quote: $(( ($1 * 90 + 99) / 100 ))"
lib/invoice.sh:3:echo "member total $(( ($1 * 90 + 99) / 100 ))"
lib/util/money.sh:6:cents_to_yen() { echo "$(( $1 / 100 )).$(( $1 % 100 ))"; }
#!/bin/bash
# Receipt for an order: bin/receipt <cents> [guest]
cd "$(dirname "$0")/.." || exit 1
source lib/receipt/line.sh
if [ "$2" = guest ]; then guest_line "$1"; else member_line "$1"; fi

#!/bin/bash
# Money helpers shared by the receipt and the reports.
# round_tenth: 10% off, rounded down (amount in cents).
round_tenth() { echo $(( ($1 * 9 + 9) / 10 )); }
# cents_to_yen: display helper.
cents_to_yen() { echo "$(( $1 / 100 )).$(( $1 % 100 ))"; }

#!/bin/bash
# Receipt lines. The member line shows the member price (10% off, rounded down).
source "$(dirname "$0")/../lib/util/money.sh" 2>/dev/null || source lib/util/money.sh
member_line() { echo "receipt $(round_tenth "$1")"; }
guest_line() { echo "receipt $1"; }

